{
  "arguments": [
    {
      "claim": "The commander exercised effective authority and control over the Military Police during the period 27 December 1992 – 20 March 1993, satisfying the control element of command responsibility.",
      "reasoning": "Customary rule 153 establishes that a superior who has effective authority and control over subordinates is liable for their crimes. The factual record shows that the Military Police was subordinated to the commander through the Chiefs of Staff after 27 November 1992, creating a direct chain of command. Article 86(2) of Additional Protocol I reinforces that such a superior relationship imposes responsibility when the superior has the power to prevent or repress breaches. Accordingly, the commander possessed the legal authority to direct, supervise, and discipline the Military Police, meeting the control requirement of Article 7(3) ICTY.",
      "citations": [
        {
          "type": "customary",
          "instrument": "customary_ihl",
          "rule_number": 153,
          "quoted_text": "Commanders and other superiors are criminally responsible for war crimes committed by their subordinates if they knew, or had reason to know, that the subordinates were about to commit or were committing such crimes and did not take all necessary and reasonable measures in their power to prevent their commission, or if such crimes had been committed, to punish the persons responsible."
        },
        {
          "type": "treaty",
          "instrument": "ap_i",
          "article": "86(2)",
          "quoted_text": "The fact that a breach of the Conventions or of this Protocol was committed by a subordinate does not absolve his superiors from penal or disciplinary responsibility, as the case may be, if they knew, or had information which should have enabled them to conclude in the circumstances at the time, that he was committing or was going to commit such a breach and if they did not take all feasible measures within their power to prevent or repress the breach."
        }
      ]
    },
    {
      "claim": "The commander knew, or had reason to know, of the murders and cruel treatment of Serb detainees committed between 27 December 1992 and 20 March 1993.",
      "reasoning": "Article 28(a)(i) of the Rome Statute requires that a commander either knew or, given the circumstances, should have known that forces under his control were committing or about to commit crimes. The detention facilities were under the direct supervision of the Military Police, which reported to the commander. The pattern of repeated abuses over several months, the proximity of the commander to the chain of command, and the fact that the crimes continued after the commander assumed authority create the requisite knowledge inference under customary rule 153 and the Rome Statute provision.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "28",
          "quoted_text": "That military commander or person either knew or, owing to the circumstances at the time, should have known that the forces were committing or about to commit such crimes;"
        },
        {
          "type": "customary",
          "instrument": "customary_ihl",
          "rule_number": 153,
          "quoted_text": "Commanders and other superiors are criminally responsible for war crimes committed by their subordinates if they knew, or had reason to know, that the subordinates were about to commit or were committing such crimes..."
        }
      ]
    },
    {
      "claim": "The commander failed to take all necessary and reasonable measures within his power to prevent or repress the murders and cruel treatment, thereby breaching his duty under Article 7(3) ICTY.",
      "reasoning": "Article 28(a)(ii) of the Rome Statute obliges a commander to take all necessary and reasonable measures to prevent or repress the commission of crimes, or to refer them to competent authorities. The factual record shows that no effective orders, investigations, or disciplinary actions were undertaken by the commander after becoming aware of the abuses. Both the Rome Statute provision and customary rule 153 require such measures; the commander’s inaction constitutes the requisite omission for command responsibility.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "28",
          "quoted_text": "That military commander or person failed to take all necessary and reasonable measures within his or her power to prevent or repress their commission or to submit the matter to the competent authorities for investigation and prosecution."
        },
        {
          "type": "customary",
          "instrument": "customary_ihl",
          "rule_number": 153,
          "quoted_text": "...and did not take all necessary and reasonable measures in their power to prevent their commission, or if such crimes had been committed, to punish the persons responsible."
        }
      ]
    },
    {
      "claim": "Taken together, the established control, knowledge, and omission satisfy the elements of Article 7(3) ICTY, and the standard of proof beyond reasonable doubt is met by the Trial Chamber’s findings.",
      "reasoning": "The Tribunal’s factual findings confirm the commander’s authority over the Military Police, his knowledge (or constructive knowledge) of the crimes, and his failure to act. Under the legal standards set out in the Rome Statute, customary IHL, and Additional Protocol I, these facts fulfill each element of superior criminal responsibility. The standard of proof required—beyond reasonable doubt—is satisfied because the Chamber’s determinations are based on corroborated evidence linking the commander to the control structure and to the omission, leaving no reasonable alternative explanation.",
      "citations": []
    }
  ]
}
